    function __ESBMC_assume(bool) internal pure {}
    function run(uint64 a, uint256 d) public payable {
        require(a < 1000000 && d < 1000000);
        bytes32 before = c.hash(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.setL1BlockValues(a, a, d, bytes32(uint256(7)), a, bytes32(uint256(8)), d, d); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        assert(reverted && c.hash() == before);
    }
    receive() external payable {}
}

