pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    L1Block c;

    function setUp() public {
        c = new L1Block();
    }

    function _run(uint64 a, uint256 d) internal {
        a = uint64(bound(uint256(a), 0, 999999));
        d = bound(d, 0, 999999);
        bytes32 before;
        try c.hash() returns (bytes32 __r) { before = __r; } catch { return; }
        bool reverted;
        try c.setL1BlockValues(a, a, d, bytes32(uint256(7)), a, bytes32(uint256(8)), d, d) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted && c.hash() == before);
    }

    function testFuzz_run(uint64 a, uint256 d) public {
        _run(a, d);
    }

    receive() external payable {}
}
